        // Ensure swapAndLiquify is enabled
        elo.setSwapAndLiquifyEnabled(true);
        vm.stopPrank();

        // Prime the contract's balance to be exactly the swap threshold
        elo.transfer(TARGET, newSwapThreshold);

        // Any subsequent transfer will now trigger the swapAndLiquify function
